function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,function(c){return{'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]})}
function fd(s){var d=new Date(s+'T00:00:00');return isNaN(d)?s:d.toLocaleDateString('en-US',{year:'numeric',month:'long',day:'numeric'})}
function ft(t){if(!t)return '';var p=t.split(':'),h=+p[0];return ((h+11)%12+1)+':'+p[1]+' '+(h<12?'AM':'PM')}
function applyBrand(){var g=function(i){return document.getElementById(i)};g('bn').textContent=SITE.name;g('bt').textContent=SITE.tagline+' \u00b7 '+SITE.place;g('fname').textContent='\u00a9 '+new Date().getFullYear()+' '+SITE.name+', '+SITE.place}
function iso(){var d=new Date(),p=function(n){return n<10?'0'+n:''+n};return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())}
function inR(p,d){var a=document.getElementById(p+'_f').value,b=document.getElementById(p+'_t').value;if(!a&&!b)return true;if(!d)return false;return(!a||d>=a)&&(!b||d<=b)}
function dateBar(p,l){return '<div class="dbar"><div><label for="'+p+'_f">'+l+': from</label><input type="date" id="'+p+'_f"></div><div><label for="'+p+'_t">to</label><input type="date" id="'+p+'_t"></div><button class="btn sm ghost" type="button" id="'+p+'_x">Clear dates</button></div>'}
