function ph(o){return o.photos&&o.photos.length?'<img src="'+o.photos[0]+'" alt="">':esc(ini(o.name))}
function readImgs(files){return Promise.all([].slice.call(files).filter(function(f){return /^image\//.test(f.type)}).map(function(f){return new Promise(function(res){var r=new FileReader();r.onload=function(){var im=new Image();im.onload=function(){var k=Math.min(1,1000/Math.max(im.width,im.height)),c=document.createElement('canvas');c.width=Math.round(im.width*k);c.height=Math.round(im.height*k);c.getContext('2d').drawImage(im,0,0,c.width,c.height);res(c.toDataURL('image/jpeg',.82))};im.onerror=function(){res(null)};im.src=r.result};r.onerror=function(){res(null)};r.readAsDataURL(f)})})).then(function(a){return a.filter(Boolean)})}
function thumbs(el,arr){el.innerHTML=arr.map(function(u,i){return '<div class="thumb"><img src="'+u+'" alt=""><button type="button" data-i="'+i+'" aria-label="Remove photo">\u00d7</button></div>'}).join('');el.onclick=function(e){var b=e.target.closest('button');if(b){arr.splice(b.dataset.i,1);thumbs(el,arr)}}}
