+'<section class="blk"><div class="page"><div class="bh"><div><h2>Why plan ahead</h2><p>Pre-arranging is a practical act of care. Here is what families tell us it gives them.</p></div></div><div class="g3">'+[['Peace of mind','Know that your wishes are recorded and understood, whatever the future holds.'],['Less burden on family','Spare your loved ones from rushed decisions and costs at a painful time.'],['Your wishes, honored','Choose cremation or a garden lawn lot, and how you would like to be remembered.']].map(function(x){return '<div class="card gb"><div class="cb"><p class="t serif">'+x[0]+'</p><p class="s">'+x[1]+'</p></div></div>'}).join('')+'</div></div></section>'
+'<section class="blk"><div class="page"><div class="bh"><div><h2>How planning ahead works</h2><p>Four simple steps, at your own pace.</p></div></div><div class="tl">'+[['Talk with us','Reach out by form or phone. A staff member listens first.'],['Choose your wishes','Cremation or a lawn lot, with flowers, urns, and caskets as they become available.'],['Put it on record','We note your choices and the family member who should be contacted.'],['Revisit any time','Review or change your plan whenever your wishes change.']].map(function(x,i){return '<div><div class="n">'+(i+1)+'</div><h3 class="serif" style="font-size:17px;margin-bottom:4px">'+x[0]+'</h3><p style="color:var(--soft);font-size:14px;margin:0">'+x[1]+'</p></div>'}).join('')+'</div></div></section>'
+'<section class="blk"><div class="page two" style="align-items:start"><div class="panel"><h3 class="serif" style="margin-bottom:4px">Your planning checklist</h3><p id="pcn" style="color:var(--faint);font-size:13px;margin:0 0 14px"></p><div id="pcl">'+['Cremation or a lawn lot','Where and when the farewell should be held','Flowers (coming soon)','An urn or casket (coming soon)','Important documents in one place','A family member we should contact'].map(function(t,i){return '<label class="chk" for="pc'+i+'"><input type="checkbox" id="pc'+i+'"> '+t+'</label>'}).join('')+'</div><p style="color:var(--faint);font-size:12.5px;margin:6px 0 0">This checklist is only for you. Nothing is saved or sent.</p></div>'
+'<form class="panel" id="plan-form"><h3 class="serif" style="margin-bottom:4px">Request a planning conversation</h3><p style="color:var(--faint);font-size:13px;margin:0 0 14px">Tell us a little and our staff will reach out by email. No payment and no commitment.</p><div id="pm"></div><div class="fr"><label for="pn">Your name</label><input id="pn" required></div><div class="fr"><label for="pe">Email</label><input id="pe" type="email" required></div><div class="fr"><label for="pa">What are you thinking about?</label><select id="pa"><option>Cremation</option><option>Lawn lot</option><option>Not sure yet</option></select></div><div class="fr"><label for="pg">Anything you would like us to know (optional)</label><textarea id="pg"></textarea></div><button class="btn">Send request</button></form></div></section>'
