function renderOL(){var q=document.getElementById('fq').value.trim().toLowerCase(),b=document.getElementById('fb').value,d=document.getElementById('fdd').value;
var r=OB.filter(function(o){return o.status!=='Draft'&&(!q||o.name.toLowerCase().indexOf(q)>-1)&&(!b||o.born>=b)&&(!d||o.died<=d)});
document.getElementById('ol').innerHTML=r.length?r.map(card).join(''):'<div class="empty" style="grid-column:1/-1">No obituaries match your search.</div>'}
